impl<T: gx::Coef> Translator<(), T> {
    /// A value from its coefficients, in blade order.
    #[inline(always)]
    #[allow(clippy::too_many_arguments)]
    pub const fn new(s: T, e01: T, e02: T, e03: T) -> Self {
        Translator { c: [s, e01, e02, e03] }
    }

    /// The identity map on `Translator`: a `Translator` with one open `Translator` slot.
    #[inline(always)]
    pub fn slot() -> Translator<(Translator,), T> {
        Translator { c: core::array::from_fn(|i| core::array::from_fn(|j| if i == j { T::one() } else { T::zero() })) }
    }

    /// Coefficient of `1`.
    #[inline(always)]
    pub fn s(&self) -> T {
        self.c[0]
    }

    /// Coefficient of `e01`.
    #[inline(always)]
    pub fn e01(&self) -> T {
        self.c[1]
    }

    /// Coefficient of `e02`.
    #[inline(always)]
    pub fn e02(&self) -> T {
        self.c[2]
    }

    /// Coefficient of `e03`.
    #[inline(always)]
    pub fn e03(&self) -> T {
        self.c[3]
    }
}

