impl<S1: gx::Slots, S2: gx::Slots, T: gx::Coef> gx::Gp<Plane<S2, T>> for Plane<S1, T> {
    type Output = Motor<gx::Cat<S1, S2>, T>;
    #[inline]
    fn gp(self, rhs: Plane<S2, T>) -> Motor<gx::Cat<S1, S2>, T> {
        let a = self.c.map(gx::SlotArr::<S1, T>);
        let b = rhs.c.map(gx::SlotArr::<S2, T>);
        Motor {
            c: [
                (a[0] * b[0] + a[1] * b[1] + a[2] * b[2]).0,
                (a[1] * b[2] - a[2] * b[1]).0,
                (-(a[0] * b[2]) + a[2] * b[0]).0,
                (a[0] * b[1] - a[1] * b[0]).0,
                (-(a[0] * b[3]) + a[3] * b[0]).0,
                (-(a[1] * b[3]) + a[3] * b[1]).0,
                (-(a[2] * b[3]) + a[3] * b[2]).0,
                <gx::Cat<S1, S2> as gx::Slots>::from_flat(&mut |_| T::zero(), 0),
            ],
        }
    }
}

impl<S1: gx::Slots, S2: gx::Slots, T: gx::Coef> gx::Gp<Line<S2, T>> for Plane<S1, T> {
    type Output = Flector<gx::Cat<S1, S2>, T>;
    #[inline]
    fn gp(self, rhs: Line<S2, T>) -> Flector<gx::Cat<S1, S2>, T> {
        let a = self.c.map(gx::SlotArr::<S1, T>);
        let b = rhs.c.map(gx::SlotArr::<S2, T>);
        Flector {
            c: [
                (-(a[1] * b[2]) + a[2] * b[1]).0,
                (a[0] * b[2] - a[2] * b[0]).0,
                (-(a[0] * b[1]) + a[1] * b[0]).0,
                (-(a[0] * b[3]) - a[1] * b[4] - a[2] * b[5]).0,
                (a[1] * b[5] - a[2] * b[4] - a[3] * b[0]).0,
                (-(a[0] * b[5]) + a[2] * b[3] - a[3] * b[1]).0,
                (a[0] * b[4] - a[1] * b[3] - a[3] * b[2]).0,
                (a[0] * b[0] + a[1] * b[1] + a[2] * b[2]).0,
            ],
        }
    }
}

